#![cfg(spawned_sim)]

const INPUT: &[u8] = include_bytes!("../regressions/refused_job_drops_in_handler_call.input");

/// The input under its own schedule and under its recorded tape.
#[test]
fn refused_job_drops_in_handler_call_tape() {
    spawned_fuzz::assert_passes_faults(INPUT, None);
}

/// The same operations under other simulator schedules.
#[spawned_macros::sim_test(seeds = 32)]
async fn refused_job_drops_in_handler_call_seeds(seed: u64) {
    spawned_fuzz::init();
    spawned_fuzz::run_body(spawned_fuzz::decode_faults(INPUT).unwrap(), seed).await;
}
